            class GEpkAjax {
                /** konstruktor */
                constructor(urls, cnt, zastupy, fragments) {
                    this.urls = urls;
                    this.cnt = cnt;
                    this.zastupy = zastupy === true ? true : false;
                    if (fragments != null)
                        this.fragments = fragments;
                }
                getRqCountAll(dfd, urls, index, output) {
                    this.cnt.log.debug(index + ". Pokouším se načíst data alternativní EPK (jiná DB).");
                    var that = this;
                    if (urls == null || urls.length === 0) {
                        return $.Deferred().resolve(null).promise();
                    }
                    const url = urls[index];
                    let path = url;
                    // DBPROFILE
                    const parts = path.split("=");
                    const dbProfile = parts[parts.length - 1];
                    this.cnt.log.debug(index + ". Alternativní EPK: ", path);
                    this.cnt.log.debug("dbProfile: " + dbProfile);
                    let method = "Isl/ElectronicSignatureBookRequest/GetAllRqCount";
                    // GPC
                    const main = $.content();
                    if (main["gpcTokenEpk"] != null) {
                        path += "&~_gpc=" + main["gpcTokenEpk"];
                    }
                    path += "&~rezim=4"; // doplněn režim automatického výběru funkce pro výčet počtů
                    new GAjax(path)
                        .get(method, {
                        filters: { supervisor: this.zastupy ? 5 : 4 },
                        fragments: this.fragments
                    })
                        .then((result) => {
                        this.cnt.log.debug(index + ". Data alternativní EPK byla načtena.");
                        if (main["gpcTokenEpk"] == null)
                            main["gpcTokenEpk"] = result.gpcToken;
                        if (result != null && result.data != null) {
                            let resultData = result.data;
                            resultData["dbProfile"] = dbProfile;
                            output.push(resultData);
                        }
                        // přejdu k dalšímu záznamu
                        index++;
                        if (urls.length === index) {
                            dfd.resolve(output);
                        }
                        else {
                            this.getRqCountAll(dfd, urls, index, output);
                        }
                    })
                        .catch(function (err) {
                        console.error(err);
                        if (err != null && err.message != null) {
                            that.cnt.log.error(err.message);
                            console.error(err.message);
                        }
                        // přejdu k dalšímu záznamu
                        index++;
                        if (urls.length === index) {
                            dfd.resolve(output);
                        }
                        else {
                            that.getRqCountAll(dfd, urls, index, output);
                        }
                    });
                    return dfd.promise();
                }
                logout(url) {
                    //@ts-ignore
                    $.content("main").logout(false, {
                        reason: "Budete přesměrování na zvolenou aplikaci", status: "success", backText: "Přepnout na zvolenou aplikaci", backScript: url, backMask: 16, backAuto: true
                    });
                }
                getGpc() {
                    const main = $.content();
                    return main["gpcTokenEpk"];
                }
                /** Načtení počtu žádostí do EPK dashboardu */
                pocetZadostiAll() {
                    var dfd = $.Deferred();
                    return this.getRqCountAll(dfd, this.urls, 0, []);
                }
            }
