                // - při aktivním nastavení kategorií důvodu podpisu
                getWflsdpoDto(ixs_dpo, cnt) {
                    var myservice = cnt.createServiceContent("Gordic.Epk.WebControls.GEpkActionsService");
                    return myservice.call("GetWflsdpoDto", { IxsDpo: ixs_dpo });
                }
