                createCommandbarPredat(dokFlag) {
                    var that = this;
                    const menuBar = [];
                    menuBar.push({
                        action: new GAction({
                            name: "actCancel",
                            caption: "jres:32000024", //RC 32000024 : Zrušit
                            align: "opposite",
                            run: function (ev, ctx) {
                                $.content(ev.currentTarget).close();
                            }
                        })
                    });
                    menuBar.push({
                        action: new GAction({
                            name: "actPonechat",
                            caption: "jres:32001161", //RC 32001161 : Ponechat stávající funkci
                            align: "opposite",
                            run: function (ev, ctx) {
                                that.createNewPripSpis("", dokFlag);
                                $.content(ev.currentTarget).close();
                            }
                        })
                    });
                    menuBar.push({
                        primary: true,
                        favorite: true,
                        action: new GAction({
                            name: "actPredat",
                            caption: "jres:32001162", //RC 32001162 : Předat
                            align: "opposite",
                            run: function (ev, ctx) {
                                var dto = {};
                                that.formPredat.findFields().gfield("model", "collect", dto);
                                if (that.formPredat.gform("isValid") === true) {
                                    that.createNewPripSpis(dto.funkce.ixs_fun, dokFlag);
                                    $.content(ev.currentTarget).close();
                                }
                            }
                        })
                    });
                    return menuBar;
                }
