                    columns.getOdesilatel(format); // odesílatel
                    columns.getSettlementReason(format); // plánovaný důvod vyřízení
                    columns.getTechnickeVlastnosti(format); // technické vlastnosti
                    if (this.povoleniFikceVyrizeni === true)
                        columns.getPrizFikceVyrizen(format); // fikce vyřízení
                    columns.getCjSpis(format, this.textCJShortDBParam, this.isFazeUsu); // Sp.Zn.
                    columns.getVecSpis(format); // věc spisu
