                registerSwipeEvents(panel) {
                    var xDown = null;
                    var yDown = null;
                    function getTouches(evt) {
                        return evt.touches || // browser API
                            evt.originalEvent.touches; // jQuery
                    }
                    function handleTouchStart(evt) {
                        // evt.preventDefault();
                        const firstTouch = getTouches(evt)[0];
                        xDown = firstTouch.clientX;
                        yDown = firstTouch.clientY;
                    }
                    ;
                    function handleTouchMove(evt) {
                        // evt.preventDefault();
                        const left = $(evt.currentTarget).children(".left");
                        const right = $(evt.currentTarget).children(".right");
                        const content = $(evt.currentTarget).children(".content");
                        if (!xDown || !yDown) {
                            return;
                        }
                        var xUp = evt.touches[0].clientX;
                        var yUp = evt.touches[0].clientY;
                        var xDiff = xDown - xUp;
                        var yDiff = yDown - yUp;
                        // console.log("xDiff", xDiff);
                        // console.log("yDiff", yDiff);
                        var diff = Math.abs(xDiff) > Math.abs(yDiff);
                        /*most significant*/
                        if (diff) {
                            if (xDiff > 0) {
                                /** remove left swipe */
                                $(left).removeClass("left-swipe");
                                $(content).removeClass("left-swipe");
                                /* right swipe */
                                $(right).addClass("right-swipe");
                                $(content).addClass("right-swipe");
                            }
                            else {
                                /** remove right swipe */
                                $(right).removeClass("right-swipe");
                                $(content).removeClass("right-swipe");
                                /* left swipe */
                                $(left).addClass("left-swipe");
                                $(content).addClass("left-swipe");
                            }
                        }
                        else {
                            if (yDiff > 0) {
                                /* down swipe */
                            }
                            else {
                                /* up swipe */
                            }
                        }
                        /* reset values */
                        xDown = null;
                        yDown = null;
                    }
                    ;
                    const containers = panel.children(".container");
                    containers.each(function () {
                        const container = $(this);
                        // mobile
                        container[0].addEventListener('touchstart', handleTouchStart, false);
                        container[0].addEventListener('touchmove', handleTouchMove, false);
                    });
                }
