                    modalWindow.findFields("checkRozhodnout").gfield("setValue", gcontent.rozhodnout.checked);
                    modalWindow.findFields("checkSchvalitVyrizeniSpisu").gfield("setValue", gcontent.schvaleniVyrizeniSpisu.checked);
                    modalWindow.findFields("checkPredat").gfield("setValue", gcontent.predat.checked);
                    modalWindow.findFields("checkPridelit").gfield("setValue", gcontent.pridelit.checked);
                    modalWindow.findFields("checkCasRazitko").gfield("setValue", gcontent.casoveRazitko.checked);
